head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil59400";
scwin.form = null;
scwin.loadTp = null;
scwin.returnVal = null;

// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.repIdYn

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.loadTp = String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.loadTp !== "undefined" && scwin.loadTp !== null ? scwin.loadTp : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "loadTp" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("loadTp"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.loadTp !== "undefined" && scwin.loadTp !== null ? scwin.loadTp : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "loadTp" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("loadTp")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.loadTp !== "undefined" && scwin.loadTp !== null ? scwin.loadTp : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "loadTp" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("loadTp"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.loadTp !== "undefined" && scwin.loadTp !== null ? scwin.loadTp : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "loadTp" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("loadTp"))));
        scwin.returnVal = String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.returnVal !== "undefined" && scwin.returnVal !== null ? scwin.returnVal : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "returnVal" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("returnVal"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.returnVal !== "undefined" && scwin.returnVal !== null ? scwin.returnVal : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "returnVal" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("returnVal")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.returnVal !== "undefined" && scwin.returnVal !== null ? scwin.returnVal : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "returnVal" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("returnVal"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.returnVal !== "undefined" && scwin.returnVal !== null ? scwin.returnVal : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "returnVal" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("returnVal"))));
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil59400.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_repIdYn", fn: function(){ return ($c.session.getUserInfo("repIdYn") === 'Y'); } }, { id: "if_repIdYn_3", fn: function(){ return ($c.session.getUserInfo("repIdYn") === 'N'); } }, { id: "if_repIdYn_2", fn: function(){ return ($c.session.getUserInfo("repIdYn") !== 'Y'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 [" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " Page] "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.form = (document.searchForm || { elements: [] });
        if (scwin.returnVal === "N") {
            await $c.win.alert('처리 중 오류가 발생하였습니다. 시스템 관리자에게 문의하여 주세요.');
        } else {
            if (scwin.loadTp === "5") {
                await $c.win.alert('제출 처리되었습니다.');
            } else {
                if (scwin.loadTp === "6") {
                    await $c.win.alert('수정요청 처리되었습니다.');
                } else {
                    if (scwin.loadTp === "7") {
                        await $c.win.alert('철회 처리되었습니다.');
                    } else {
                        if (scwin.loadTp === "4") {
                            await $c.win.alert('삭제 처리되었습니다.');
                        }
                    }
                }
            }
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil59400.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil59400' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_viewDetail();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        await scwin.initPageIndex()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil59400.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_pageList_oncellclick
 * @description grd_pageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_pageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["listProcsStatCd"] === '33' || r["listProcsStatCd"] === '36') { await scwin.adjReqPop(r["bzProcsNo"], "210", "80"); return; } if (r["listProcsStatCd"] === '30' || r["listProcsStatCd"] === '35' || r["listProcsStatCd"] === '37') { await scwin.editStatus(r["bzProcsNo"], "applSubmit", "제출"); return; } return; } if (r["listProcsStatCd"] !== '30' && r["listProcsStatCd"] !== '37' && r["listProcsStatCd"] !== '35') { await scwin.viewDetail(r["bzProcsNo"], "8"); return; }
        if (r["listProcsStatCd"] === '30') { await scwin.viewDetail(r["bzProcsNo"], "1"); return; }
        if (r["listProcsStatCd"] === '35') { await scwin.viewDetail(r["bzProcsNo"], "1"); return; }
        if (r["listProcsStatCd"] === '37') { await scwin.viewDetail(r["bzProcsNo"], "1"); return; }
        await scwin.viewDetail(r["bzProcsNo"], "9"); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_newWrite_onclick
 * @description 「신규작성」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_newWrite_onclick = function(e){
    try {
        scwin.newWrite()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil59400.btn_newWrite_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_82_onclick
 * @description krxpage_pagenavigator_82 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_82_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_viewDetailReq').set('pageIndex', pi);
        await scwin.tx_viewDetail();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil59400.krxpage_pagenavigator_82_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_viewDetail
 * @description view Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_viewDetail = async function () {
    const sbmOptions = {
        id: "tx_viewDetail",
        method: "post",
        action: "/listInvstg/specyValuAppl.do",
        ref: "dma_viewDetailReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_82").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/listInvstg/specyValuAppl.do",
        ref: "dma_SearchReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_EditStatus
 * @description Edit Status 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_EditStatus = async function () {
    const sbmOptions = {
        id: "tx_fn_EditStatus",
        method: "post",
        action: "/listInvstg/specyValuAppl.do",
        ref: "dma_EditStatusReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initPageIndex = async function () {
    $c.util.getComponent('dma_viewDetailReq').set('pageIndex', 1);
    await scwin.search();
};

/**
 * @method
 * @name grd_pageList_fmt_column5
 * @description grd page List fmt column5 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_fmt_column5 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "rsltNotiDd") ?? '') : '');
        if (v !== '') { return (console.error('[sdd] 미실현 라벨 갈래: column5 (expression)'), String(data ?? '')); }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pageList.column5" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_pageList_fmt_column8
 * @description grd page List fmt column8 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_fmt_column8 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "listProcsStatCd") ?? '') : '');
        if (['33','36'].indexOf(v) >= 0) { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "수정요청" + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pageList.column8" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_pageList_fillAct
 * @description grd page List fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            let v = '-';
            if (r) { if (r["listProcsStatCd"] === '33' || r["listProcsStatCd"] === '36') { v = "수정요청"; } else if (r["listProcsStatCd"] === '30' || r["listProcsStatCd"] === '35' || r["listProcsStatCd"] === '37') { v = "제출"; } }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.fillAct' });
    }
};

/**
 * @method
 * @name viewDetail
 * @description view Detail 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} strLoadTp strLoadTp
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewDetail = async function (bzProcsNo, strLoadTp) {
    $c.util.getComponent('dma_viewDetailReq').set('bzProcsNo', bzProcsNo);
    scwin.form.action = '/listInvstg/specyValuAppl.do';
    $c.util.getComponent('dma_viewDetailReq').set('method', 'editForm');
    $c.util.getComponent('dma_viewDetailReq').set('loadTp', strLoadTp);
    await scwin.tx_viewDetail();
};

/**
 * @method
 * @name newWrite
 * @description new Write 처리
 * @returns {void}
 * @hidden N
 */
scwin.newWrite = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil59410/jldfil59410.xml');
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    scwin.form.action = "/listInvstg/specyValuAppl.do";
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name editStatus
 * @description edit Status 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} strMethod strMethod
 * @param {String} strMsg strMsg
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.editStatus = async function (bzProcsNo, strMethod, strMsg) {
    scwin.form.action = "/listInvstg/specyValuAppl.do";
    $c.util.getComponent('dma_viewDetailReq').set('method', strMethod);
    $c.util.getComponent('dma_viewDetailReq').set('bzProcsNo', bzProcsNo);
    if (await $c.win.confirm(strMsg + '하시겠습니까?')) {
        await scwin.tx_fn_EditStatus();
    }
};

/**
 * @method
 * @name adjReqPop
 * @description adj Req Pop 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} listInvstgBzTpCd listInvstgBzTpCd
 * @param {String} listBzDtlTpCd listBzDtlTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.adjReqPop = async function (bzProcsNo, listInvstgBzTpCd, listBzDtlTpCd) {
    w = '500';
    h = '250';
    l = screen.width / 2 - w / 2;
    t = screen.height / 2 - h / 2;
    const corpSearchURL = '/jldfil59410/jldfil59410.xml';
    await $c.win.openPopup(corpSearchURL, { id: "AdjReqPop", scrollbars: false, resizable: false, width: "500", height: "250", type: "pageFramePopup" }, { method: "selectAvailableAdjReq", bzProcsNo: bzProcsNo, listInvstgBzTpCd: listInvstgBzTpCd, listBzDtlTpCd: listBzDtlTpCd });
};
